& { $apps = @(); $paths = @("HKLM:\Software\Microsoft\Windows\CurrentVersion\Uninstall\*", "HKLM:\Software\Wow6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*", "HKCU:\Software\Microsoft\Windows\CurrentVersion\Uninstall\*"); $regApps = Get-ItemProperty $paths -ErrorAction SilentlyContinue | Where-Object { $_.DisplayName -and $_.DisplayName.Trim() -ne "" } | Select-Object @{N="Name";E={$_.DisplayName.Trim()}}, @{N="Version";E={if ($_.DisplayVersion) {$_.DisplayVersion.Trim()} else {"N/A"}}}; if ($regApps) { $apps += $regApps }; $uwpApps = Get-AppxPackage -AllUsers -ErrorAction SilentlyContinue | Where-Object { $_.Name -and $_.Name.Trim() -ne "" } | Select-Object @{N="Name";E={$_.Name.Trim()}}, @{N="Version";E={$_.Version.Trim()}}; if ($uwpApps) { $apps += $uwpApps }; $optApps = Get-WindowsOptionalFeature -Online -ErrorAction SilentlyContinue | Where-Object { $_.State -eq "Enabled" } | Select-Object @{N="Name";E={$_.FeatureName}}, @{N="Version";E={"Built-in Feature"}}; if ($optApps) { $apps += $optApps }; $final = $apps | Group-Object Name | ForEach-Object { $_.Group | Select-Object -First 1 } | Sort-Object Name; $final | Format-Table -AutoSize; Write-Host "`n=========================================" -ForegroundColor Cyan; Write-Host " TOTAL UNIQUE APPS DETECTED: $($final.Count) " -ForegroundColor Yellow -BackgroundColor DarkGreen; Write-Host "=========================================" -ForegroundColor Cyan }
